import * as React from "react";
import Layout from "../components/layout";
import { graphql, PageProps } from "gatsby";
import  data  from "../data/data.json";
import { UserProfile } from "../interfaces";
import { useTranslation } from "gatsby-plugin-react-i18next";
import Palette from "../components/palette";
import EmailForm from "../components/emailForm";

const userData: UserProfile = data;

const IndexPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();
  return (
    <Layout data={userData}>
      <Palette />
      <section className={styles.container}>

        <h1>{userData.name}</h1>

        <article className={styles.section} id={userData.menu[0]}>
          <h2 className={styles.title}>{t('home.title')}</h2>
        </article>

        <article className={styles.section} id={userData.menu[1]}>
          <h2 className={styles.title}>{t('home.title')}</h2>
        </article>

        <article className={styles.section} id={userData.menu[2]}>
          <h2 className={styles.title}>{t('home.title')}</h2>
        </article>

        <article className={styles.section} id={userData.menu[3]}>
          <h2 className={styles.title}>{t('home.title')}</h2>
        </article>

        <article className={styles.section} id={userData.menu[4]}>
          <h2 className={styles.title}>{t('home.title')}</h2>
          <EmailForm />
        </article>

      </section>
    </Layout>
  )
}

export default IndexPage


export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  container: "flex flex-col justify-center items-center w-full bg-secondary",
  section: "flex h-96 bg-primary my-8 w-full border border-primary rounded-lg shadow-md",
  title: "text-4xl text-accent",
}